type webhookSourceRow struct {
	src database.WorkspaceGitHubSource
}

func (r webhookSourceRow) Scan(dest ...any) error {
	values := []any{
		r.src.ID,
		r.src.WorkspaceID,
		r.src.RepoURL,
		r.src.RepoOwner,
		r.src.RepoName,
		r.src.DefaultBranch,
		r.src.CreatedAt,
		r.src.UpdatedAt,
	}
	if len(dest) != len(values) {
		return fmt.Errorf("expected %d scan destinations, got %d", len(values), len(dest))
	}
	for i := range dest {
		switch d := dest[i].(type) {
		case *pgtype.UUID:
			*d = values[i].(pgtype.UUID)
		case *string:
			*d = values[i].(string)
		case **string:
			*d = values[i].(*string)
		case *pgtype.Timestamptz:
			*d = values[i].(pgtype.Timestamptz)
		default:
			return fmt.Errorf("unsupported scan destination %T", dest[i])
		}
	}
	return nil
}

